function fillPuzzle(board) {
  function ok(i, j, d) {
    for (let t = 0; t < 9; t++) {
      if (board[i][t] === d || board[t][j] === d) return false;
      if (board[3 * Math.floor(i / 3) + Math.floor(t / 3)][3 * Math.floor(j / 3) + t % 3] === d) return false;
    }
    return true;
  }
  function go(p) {
    while (p < 81 && board[Math.floor(p / 9)][p % 9] !== ".") p++;
    if (p === 81) return true;
    const i = Math.floor(p / 9), j = p % 9;
    for (let d = 1; d <= 9; d++) { const c = String(d); if (ok(i, j, c)) { board[i][j] = c; if (go(p + 1)) return true; board[i][j] = "."; } }
    return false;
  }
  go(0);
}
